"], "definicion": "Dificultad específica y persistente de aprendizaje relacionada con lectura, reconocimiento de palabras o decodificación.", "matiz": "No indica baja inteligencia ni se reduce a invertir letras.", "fuentes": ["learn"]}, {"id": "disortografia", "termino": "Disortografía", "otros_nombres": ["Dysorthography"], "categoria": "Perfiles y diagnósticos", "naturaleza": "Clínico", "perfiles": ["Aprendizaje"], "definicion": "Dificultad persistente en el aprendizaje y aplicación de la ortografía.", "matiz": "No se usa como categoría separada en todas las clasificaciones.", "fuentes": ["written"]}, {"id": "dispraxia-tdc", "termino": "Dispraxia / TDC", "otros_nombres": ["DCD", "developmental coordination disorder"], "categoria": "Perfiles y diagnósticos", "naturaleza": "Clínico", "perfiles": ["Coordinación"], "definicion": "Dificultades del desarrollo de la coordinación motora que interfieren en actividades cotidianas.", "matiz": "«Dispraxia» tiene usos más amplios; no confundir con apraxia del habla.", "fuentes": ["dcd"]}, {"id": "doble-empatia", "termino": "Doble empatía", "otros_nombres": ["Double empathy problem"], "categoria": "Comunicación y lenguaje", "naturaleza": "En investigación", "perfiles": ["Autismo"], "definicion": "Propuesta que sitúa algunas dificultades de comprensión entre autistas y no autistas en la interacción mutua.", "matiz": "Cuestiona explicaciones que atribuyen toda dificultad a una sola persona.", "fuentes": ["double"]}, {"id": "doble-excepcionalidad", "termino": "Doble excepcionalidad", "otros_nombres": ["Twice-exceptional", "2e"], "categoria": "Perfiles y diagnósticos", "naturaleza": "Educativo", "perfiles": ["Altas capacidades"], "definicion": "Coexistencia de altas capacidades y una discapacidad o dificultad que requiere apoyos.", "matiz": "Las fortalezas pueden ocultar necesidades, y las dificultades ocultar fortalezas.", "fuentes": ["gift"]}, {"id": "eclipsamiento-diagnostico", "termino": "Eclipsamiento diagnóstico", "otros_nombr